      font-weight: 700;
      cursor: pointer;
      transition: all 0.18s ease;
      text-align: center;
      white-space: nowrap;
    }
    .seg-btn.active {
      background: var(--primary-btn-bg, #4338ca);
      color: #fff;
      box-shadow: 0 2px 8px rgba(0,0,0,0.2);
    }

    /* Multi-Select Dropdown Component (Locations, Target Roles, Core Skills) */
    .ms-dropdown-wrap {
      position: relative;
      width: 100%;
    }
    .ms-trigger {
      width: 100%;
      min-height: 34px;
      background: var(--bg-surface-2);
      border: 1px solid var(--border-color);
      border-radius: 8px;
      padding: 5px 8px;
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 6px;
      cursor: pointer;
      font-size: 11px;
      color: var(--text-main);
    }
    .ms-trigger:hover {
      border-color: var(--primary);
    }
    .ms-chips {
      display: flex;
      flex-wrap: wrap;
      gap: 4px;
      flex: 1;
    }
    .ms-chip {
      display: inline-flex;
      align-items: center;
      gap: 4px;
      padding: 3px 7px;
      border-radius: 6px;
      background: var(--bg-surface);
      color: var(--text-main);
      border: 1px solid var(--primary);
      font-size: 10.5px;
      font-weight: 700;
    }
    .ms-chip-rm {
      cursor: pointer;
      font-weight: 900;
      opacity: 0.85;
    }
    .ms-menu {
      position: relative;
      margin-top: 4px;
      background: var(--bg-surface);
      border: 1.5px solid var(--primary);
      border-radius: 10px;
      padding: 6px;
      max-height: 170px;
      overflow-y: auto;
      box-shadow: 0 12px 28px rgba(0,0,0,0.55);
      z-index: 80;
    }
    .ms-opt {
      display: flex;
      align-items: center;
      gap: 7px;
      padding: 6px 8px;
      border-radius: 6px;
      font-size: 11px;
      font-weight: 600;
      color: var(--text-main);
      cursor: pointer;
    }
    .ms-opt:hover {
      background: var(--bg-surface-2);
    }

    /* Smooth Cards & Controls */
    .m-card {
      background: var(--bg-surface);
      border: 1px solid var(--border-color);
      border-radius: 14px;
      padding: 11px 12px;
      margin-bottom: 10px;
      box-shadow: var(--card-shadow);
      transition: transform 0.15s ease, border-color 0.15s ease;
    }
    .m-btn {
      min-height: 30px;
      min-width: 30px;
      padding: 6px 10px;
      border-radius: 8px;
      border: 1px solid transparent;
      font-size: 11px;
      font-weight: 700;
      cursor: pointer;
      display: inline-flex;
      align-items: center;
      justify-content: center;
      gap: 4px;
      transition: all 0.15s ease;
    }
    .m-btn:active { transform: scale(0.96); }
    .m-btn-primary { background: var(--primary-btn-bg, #4338ca); color: #fff; }
    .m-btn-success { background: var(--success-btn-bg, #047857); color: #fff; }
    .m-btn-danger { background: #be123c; color: #fff; border-color: #be123c; }
    .m-btn-warning { background: var(--warning-soft); color: var(--warning); border-color: rgba(251,191,36,0.35); }
    .m-btn-ghost { background: var(--bg-surface-2); color: var(--text-secondary); border-color: var(--border-color); }

    /* ==========================================================================
       2.4 INTERACTIVE SWIPE DECK FOR JOBS
       ========================================================================== */
    .swipe-stage {
      position: relative;
      min-height: 0;
      padding-bottom: 8px;
      margin-bottom: 14px;
      perspective: 1000px;
      user-select: none;
    }
    .swipe-card-bg2 {
      position: absolute;
      top: 14px; left: 16px; right: 16px; bottom: 0;
      background: var(--bg-surface-2);
      border: 1px solid var(--border-color);
      border-radius: 20px;
      transform: scale(0.92) translateY(12px);
      opacity: 0.45;
      z-index: 1;
      pointer-events: none;
    }
    .swipe-card-bg1 {
      position: absolute;
      top: 7px; left: 8px; right: 8px; bottom: 0;
      background: var(--bg-surface);
      border: 1px solid var(--border-color);
      border-radius: 20px;
      transform: scale(0.96) translateY(6px);
      opacity: 0.75;
      z-index: 2;
      pointer-events: none;
    }
    .swipe-card {
      position: relative;
      z-index: 3;
      background: var(--bg-surface);
      border: 1.5px solid var(--border-color);
      border-radius: 20px;
      padding: 15px;
      box-shadow: 0 16px 38px rgba(0,0,0,0.35);
      cursor: grab;
      transition: transform 0.28s cubic-bezier(0.22, 1, 0.36, 1), opacity 0.25s ease;
      touch-action: pan-y;
    }
    .swipe-card:active { cursor: grabbing; }
    .swipe-stamp {
      position: absolute;
      top: 18px;
      padding: 4px 12px;
      border-radius: 8px;
      font-size: 14px;
      font-weight: 900;
      letter-spacing: 1px;
      text-transform: uppercase;
      opacity: 0;
      pointer-events: none;
      transition: opacity 0.12s ease;
      z-index: 10;
    }
    .swipe-stamp.approve {
      left: 16px;
      color: #10b981;
      border: 3px solid #10b981;
      background: rgba(16, 185, 129, 0.15);
      transform: rotate(-12deg);
    }
    .swipe-stamp.nope {
      right: 16px;
      color: #f43f5e;
      border: 3px solid #f43f5e;
      background: rgba(244, 63, 94, 0.15);
      transform: rotate(12deg);
    }
    .swipe-dock {
      display: flex;
      justify-content: center;
      align-items: center;
      gap: 10px;
      padding: 6px 0 4px 0;
    }
    .swipe-fab {
      width: 46px;
      height: 46px;
      border-radius: 50%;
      border: 1.5px solid var(--border-color);
      background: var(--bg-surface);
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 18px;
      cursor: pointer;
      box-shadow: 0 6px 18px rgba(0,0,0,0.28);
      transition: all 0.18s cubic-bezier(0.22, 1, 0.36, 1);
    }
    .swipe-fab:hover { transform: scale(1.08); }
    .swipe-fab:active { transform: scale(0.93); }
    .swipe-fab.pass { color: #f43f5e; border-color: rgba(244,63,94,0.4); }
    .swipe-fab.info { color: #38bdf8; border-color: rgba(56,189,248,0.4); width: 42px; height: 42px; font-size: 15px; }
    .swipe-fab.like { color: #10b981; border-color: rgba(16,185,129,0.45); width: 52px; height: 52px; font-size: 21px; }
    .swipe-fab.super { color: #a855f7; border-color: rgba(168,85,247,0.4); width: 42px; height: 42px; font-size: 15px; }

    /* ==========================================================================
       2.5 LEFT-TO-RIGHT HALF-SCREEN SLIDER (PULLS FROM LEFT TO HALF SCREEN!)
       ========================================================================== */
    .left-edge-pull-tab {
      position: absolute;
      left: 0;
      top: 52%;
      transform: translateY(-50%);
      background: linear-gradient(180deg, var(--primary), var(--accent));
      color: #ffffff;
      padding: 8px 1px;
      width: 13px;
      min-width: 13px;
      max-width: 13px;
      border-radius: 0 7px 7px 0;
      font-size: 7.5px;
      line-height: 1;
      font-weight: 800;
      writing-mode: vertical-rl;
      text-orientation: mixed;
      display: flex;
      align-items: center;
      justify-content: center;
      cursor: pointer;
      z-index: 38;
      opacity: 0.92;
      box-shadow: 2px 0 8px rgba(99, 102, 241, 0.35);
      border: 1px solid rgba(255,255,255,0.24);
      border-left: none;
      letter-spacing: 0.4px;
      transition: all 0.2s ease;
      user-select: none;
      touch-action: none;
    }
    .left-edge-pull-tab::after {
      content: '';
      position: absolute;
      top: -10px;
      bottom: -10px;
      left: 0;
      right: -10px;
    }
    .left-edge-pull-tab.list-mode-tab {
      width: 22px !important;
      min-width: 22px !important;
      max-width: 22px !important;
      padding: 12px 3px !important;
      font-size: 9px !important;
      border-radius: 0 10px 10px 0 !important;
      box-shadow: 3px 0 14px rgba(56, 189, 248, 0.55) !important;
    }
    .left-edge-pull-tab:hover { width: 15px; max-width: 15px; opacity: 1; }
    .left-edge-pull-tab.list-mode-tab:hover { width: 24px !important; max-width: 24px !important; opacity: 1; }

    .slider-backdrop {
      position: absolute;
      top: 71px;
      left: 0;
      right: 0;
      bottom: 0;
      background: rgba(2, 6, 23, 0.38);
      z-index: 39;
      display: none;
      cursor: pointer;
    }
    .slider-backdrop.open {
      display: block;
    }

    .half-slider {
      position: absolute;
      top: 71px;
      bottom: 0;
      left: 0;
      width: 75%;
      background: var(--bg-glass);
      backdrop-filter: blur(18px);
      -webkit-backdrop-filter: blur(18px);
      border-right: 2.5px solid var(--primary);
      border-radius: 0 20px 20px 0;
      box-shadow: 16px 0 42px rgba(0,0,0,0.62);
      z-index: 40;
      display: flex;
      flex-direction: column;
      transition: transform 0.26s cubic-bezier(0.22, 1, 0.36, 1);
      overflow: hidden;
    }
    .half-slider.state-closed {
      transform: translateX(-104%);
      pointer-events: none;
    }
    .half-slider.state-half,
    .half-slider.state-open,
    .half-slider.state-full {
      width: 75%;
      transform: translateX(0);
    }

    .slider-right-edge-grip {
      position: absolute;
      right: 0;
      top: 50%;
      transform: translateY(-50%);
      width: 12px;
      height: 52px;
      background: var(--primary);
      color: #fff;
      border-radius: 6px 0 0 6px;
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 8px;
      font-weight: 800;
      cursor: pointer;
      z-index: 45;
      box-shadow: -2px 0 8px rgba(0,0,0,0.35);
      user-select: none;
    }

    .slider-handle-bar {
      padding: 8px 10px;
      background: var(--bg-surface);
      border-bottom: 1px solid var(--border-color);
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 6px;
      flex-shrink: 0;
    }
    .slider-body {
      flex: 1;
      overflow-y: auto;
      padding: 9px 14px 18px 10px;
    }

    /* A4 Mini Resume Sheet */
    .a4-mini {
      background: #ffffff;
      color: #0f172a;
      border-radius: 8px;
      padding: 14px;
      font-family: Georgia, 'Times New Roman', serif;
      font-size: 10.2px;
      line-height: 1.38;
      box-shadow: 0 8px 25px rgba(0,0,0,0.35);
      border: 1px solid #cbd5e1;
      width: 100%;
      max-width: 100%;
      box-sizing: border-box;
      overflow-x: hidden;
      word-wrap: break-word;
      overflow-wrap: anywhere;
      -webkit-text-size-adjust: 100%;
      text-size-adjust: 100%;
    }
    .a4-mini .job-header,
    .a4-mini .cert-row,
    .a4-mini .edu-row {
      display: flex;
      justify-content: space-between;
      align-items: baseline;
      flex-wrap: wrap;
      gap: 2px 8px;
    }

    /* Form Controls inside Mobile & Staging */
    .m-input, .m-select, .m-textarea {
      width: 100%;
      background: var(--bg-surface-2);
      border: 1px solid var(--border-color);
      color: var(--text-main);
      padding: 6px 9px;
      border-radius: 8px;
      font-size: 11px;
      outline: none;
    }
    .m-input:focus, .m-select:focus, .m-textarea:focus {
      border-color: var(--primary);
    }

    /* Toast Notification */
    .m-toast {
      position: fixed;
      bottom: 22px;
      right: 22px;
      background: var(--bg-surface);
      color: var(--text-main);
      border: 1.5px solid var(--primary);
      border-radius: 12px;
      padding: 10px 16px;
      font-size: 12px;
      font-weight: 700;
      box-shadow: 0 12px 30px rgba(0,0,0,0.5);
      z-index: 9999;
      display: none;
      align-items: center;
      gap: 8px;
    }

    /* Desktop Right-Side Companion Cards */
    .stat-card {
      background: var(--bg-surface);
      border: 1px solid var(--border-color);
      border-radius: 14px;
      padding: 14px 16px;
      box-shadow: var(--card-shadow);
    }
    .stat-val { font-size: 24px; font-weight: 800; line-height: 1.1; margin-bottom: 4px; }
    .stat-lbl { font-size: 11.5px; color: var(--text-muted); font-weight: 600; }
    .card-custom {
      background: var(--bg-surface);
      border: 1px solid var(--border-color);
      border-radius: 16px;
      padding: 16px 18px;
      margin-bottom: 16px;
      box-shadow: var(--card-shadow);
    }
    table.qa-table { width: 100%; border-collapse: collapse; font-size: 12.5px; }
    table.qa-table th, table.qa-table td { padding: 9px 11px; border-bottom: 1px solid var(--border-color); text-align: left; }
    table.qa-table th { color: var(--text-muted); font-size: 10.5px; text-transform: uppercase; letter-spacing: 0.5px; background: var(--bg-surface-2); }
    .pass-pill { background: var(--success-soft); color: var(--success); padding: 3px 8px; border-radius: 6px; font-weight: 700; font-size: 11px; }
  </style>
</head>
