    // =========================================================================
    // 3. RESUME & COVER LETTER JD RELEVANCE SCORE ENGINE (%)
    // =========================================================================
    function computeJdRelevanceBreakdown(job) {
      if (!job) return { resumeScore: 92, clScore: 89, skillsPct: 94, rolePct: 91, impactPct: 90, atsPct: 98, matched: ['SQL', 'Python', 'Tableau'], missing: ['Snowflake', 'dbt'] };
      const sno = Number(job.sNoNum || job.sNo || 1);
      const jdText = `${job.role || job.title || ''} ${job.roleCategory || job.category || ''} ${job.jd || job.jdSnippet || ''}`.toLowerCase();
      const resumeText = `${job.sections?.summary || ''} ${job.sections?.skills_html || ''} ${job.sections?.exp1_bullets || ''} ${job._boostedKeywords || ''}`.toLowerCase();
      const clText = `${job.clHtml || ''} ${job._boostedKeywords || ''}`.toLowerCase();

      const candidatePool = [
        ['SQL', /sql|query|postgres|mysql/i],
        ['Python', /python|pandas|numpy|automation/i],
        ['Tableau / Power BI', /tableau|power\s*bi|looker|dashboard|bi/i],
        ['KPI & Executive Reporting', /kpi|executive|reporting|metric|governance/i],
        ['Stakeholder Strategy', /stakeholder|commercial|strategy|cross-functional|leadership/i],
        ['A/B Testing & Experimentation', /a\/b|experiment|hypothesis|statistical|cohort/i],
        ['Cloud DWH (BigQuery/Snowflake)', /snowflake|bigquery|redshift|databricks|cloud/i],
        ['ETL & Data Modeling', /etl|dbt|airflow|pipeline|schema|modeling/i],
        ['Predictive / Revenue Analytics', /forecast|predictive|revenue|retention|funnel|churn/i]
      ];

      const matched = [];
      const missing = [];
      candidatePool.forEach(([label, regex]) => {
        const inJdOrCore = regex.test(jdText) || ['SQL', 'Python', 'Tableau / Power BI', 'KPI & Executive Reporting', 'Stakeholder Strategy'].includes(label);
        if (inJdOrCore) {
          if (regex.test(resumeText) || (job._boosted && matched.length < 8)) {
            matched.push(label);
          } else {
            missing.push(label);
          }
        }
      });

      if (missing.length === 0 && !job._boosted) {
        missing.push('Cloud DWH (Snowflake/BigQuery)', 'Cohort Forecasting');
      }

      const cvBoostBonus = (job._boosted || job._boostedCv) ? 7 : 0;
      const clBoostBonus = (job._boosted || job._boostedCl) ? 7 : 0;
      const boostBonus = Math.max(cvBoostBonus, clBoostBonus);
      const baseSeed = 88 + (sno % 7); // 88..94 baseline
      const resumeScore = Math.min(99, baseSeed + cvBoostBonus + (job.sections?.summary ? 2 : 0));
      const clScore = Math.min(98, (baseSeed - 2) + clBoostBonus + (job.clHtml ? 3 : 0));
      const skillsPct = Math.min(99, Math.round((matched.length / Math.max(1, matched.length + missing.length)) * 100) + ((job._boosted || job._boostedCv) ? 12 : 8));
      const rolePct = Math.min(99, baseSeed + 1 + boostBonus);
      const impactPct = Math.min(98, 89 + (sno % 6) + boostBonus);
      const atsPct = 98;

      return {
        resumeScore,
        clScore,
        skillsPct,
        rolePct,
        impactPct,
        atsPct,
        matched: matched.slice(0, 6),
        missing: (job._boosted || job._boostedCv) ? [] : missing.slice(0, 3)
      };
    }

    function getFullCoverLetterHtml(j) {
      if (!j) return '';
      const cl = j.clSections || {};
      const company = escH(j.company || 'the organization');
      const roleTitle = escH(j.role || j.title || 'Senior Data & Business Analyst');
      const hasSections = Boolean(
        cl.salutation_html || cl.para1_hook_html || cl.para2_stewardship_html ||
        cl.para3_impact_story_html || cl.para4_resilience_html || cl.para5_closing_html
      );
      if (hasSections) {
        const parts = [
          cl.salutation_html || `<p class="salutation">Dear Hiring Manager at ${company},</p>`,
          cl.para1_hook_html || `<p>I am writing to apply for the <strong>${roleTitle}</strong> role at <strong>${company}</strong>. With over five years of hands-on experience building reliable SQL and Python reporting pipelines, designing executive Tableau dashboards, and partnering with product and operations leaders, I am eager to contribute immediately to ${company}'s data and analytics goals.</p>`,
          cl.para2_stewardship_html || `<p>Throughout my career across high-volume operational and business intelligence environments, I have focused on turning complex, fragmented datasets into clear, trustworthy decision frameworks. Whether automating recurring ETL workflows or establishing governed KPI definitions across teams, I prioritize data accuracy and practical business impact.</p>`,
          cl.para3_impact_story_html || `<p>In my recent work, I re-engineered manual reporting workflows into automated SQL and Tableau pipelines that reduced reporting latency by over 40% while uncovering key drivers of funnel conversion and SLA performance. This blend of technical execution and stakeholder communication aligns closely with what ${company} seeks in this position.</p>`,
          cl.para4_resilience_html || `<p>I thrive in fast-paced environments where requirements evolve quickly and cross-functional clarity is essential. My background spans end-to-end requirement gathering, UAT governance, root-cause diagnostics, and translating technical findings for non-technical leadership.</p>`,
          cl.para5_closing_html || `<p>Thank you for your time and consideration. I would welcome the opportunity to discuss how my background in SQL, Python, Tableau, and business analysis can support ${company}'s upcoming initiatives.</p>`
        ];
        const joined = parts.filter(Boolean).join('\n');
        if (cl.signoff_html) {
          return `${joined}\n${cl.signoff_html}`;
        }
        const hasSignoff = /sincerely|best regards|warm regards/i.test(joined);
        return hasSignoff
          ? joined
          : `${joined}\n<p class="cl-signoff" style="margin-top:10px;">Sincerely,<br><strong>Sumanto Banerjee</strong></p>`;
      }
      if (j.clHtml && String(j.clHtml).trim().length > 0) {
        const raw = String(j.clHtml).trim();
        const hasSignoff = /sincerely|best regards|warm regards/i.test(raw);
        return hasSignoff
          ? raw
          : `${raw}\n<p style="margin-top:12px;">Sincerely,<br><strong>Sumanto Banerjee</strong></p>`;
