      const j = jobs.find(x => String(x.sNo) === String(sNo)) || getSelectedJob();
      const rel = computeJdRelevanceBreakdown(j);
      const addedKeywords = rel.missing.length ? rel.missing.join(', ') : 'Snowflake, BigQuery, dbt, Cohort Forecasting';
      j._boostedKeywords = addedKeywords;
      if (!j.sections) j.sections = {};
      if (!j.resumeSections) j.resumeSections = {};
      if (!j.clSections) j.clSections = {};

      if (mode === 'both' || mode === 'cv') {
        j._boostedCv = true;
        if (mode === 'both') j._boosted = true;
        const boostedSum = `<p><strong>Senior Data &amp; Business Analyst</strong> tailored for <strong>${escH(j.company)}</strong> (${escH(j.role || j.title)}) with end-to-end expertise in <strong>SQL, Python, Tableau, ${escH(addedKeywords)}</strong>, automated KPI governance, and executive decision pipelines.</p>`;
        const boostedSkills = `<ul><li><strong>Core Analytics &amp; JD Stack:</strong> SQL, Python, Tableau, Power BI, Looker Studio, <strong>${escH(addedKeywords)}</strong>, A/B Testing, ETL Data Modeling, Executive Storytelling</li></ul>`;
        j.sections.summary = boostedSum;
        j.resumeSections.summary_html = boostedSum;
        j.sections.skills_html = boostedSkills;
        j.resumeSections.skills_html = boostedSkills;
      }
      if (mode === 'both' || mode === 'cl') {
        j._boostedCl = true;
        if (mode === 'both') j._boosted = true;
        j.clSections.para2_stewardship_html = `<p>Throughout my career across high-volume operational and business intelligence environments, I have focused on turning complex, fragmented datasets into clear decision frameworks using <strong>SQL, Python, Tableau, and ${escH(addedKeywords)}</strong>. Whether automating recurring ETL workflows or establishing governed KPI definitions across teams, I prioritize data accuracy and measurable commercial impact for <strong>${escH(j.company)}</strong>.</p>`;
        j.clHtml = getFullCoverLetterHtml(j);
      }

      const newRel = computeJdRelevanceBreakdown(j);
      const labelMap = { both: 'Both CV & CL', cv: 'CV', cl: 'CL' };
      notifyToast(`🚀 Boosted ${labelMap[mode] || 'Both'} (${addedKeywords})! CV: ${newRel.resumeScore}% • CL: ${newRel.clScore}%`);
      renderSimulator();
      renderHalfSlider();
      try {
