    function isSliderCurrentlyAllowed() {
      if (currentPhoneTab === 'a4') return true;
      if (currentPhoneTab === 'jobs') {
        if (jobsViewMode === 'list') return Boolean(activeListJobSno);
        return true;
      }
      if (currentPhoneTab === 'linkedin') {
        if (liSubTab === 'actions') return Boolean(activeLiPostId);
        if (liSubTab === 'connections') return Boolean(activeLiConnId);
        if (liSubTab === 'milestones') return Boolean(activeLiMsId);
      }
      return false;
