    function handlePullTabTouchStart(e) {
      if (e) e.stopPropagation();
      if (!isSliderCurrentlyAllowed()) return;
      window._pullTabStartX = (e.touches && e.touches[0]) ? e.touches[0].clientX : 0;
    }

    function handlePullTabTouchMove(e) {
      if (e) e.stopPropagation();
      if (!isSliderCurrentlyAllowed()) return;
      const cx = (e.touches && e.touches[0]) ? e.touches[0].clientX : 0;
      if (cx - (window._pullTabStartX || 0) > 6 && sliderState === 'closed') {
        setSliderState('half');
      }
    }

    function handlePullTabTouchEnd(e) {
      if (e) {
        e.stopPropagation();
        if (e.cancelable) e.preventDefault();
      }
      if (!isSliderCurrentlyAllowed()) return;
      if (sliderState === 'closed') {
        setSliderState('half');
      }
    }

    function syncPullTabDomState(pullTab) {
      if (!pullTab) return;
      const isLiReviewMode = (currentPhoneTab === 'linkedin' && liSubTab === 'actions');
      const isLiConnMode = (currentPhoneTab === 'linkedin' && liSubTab === 'connections');
      const isLiMsMode = (currentPhoneTab === 'linkedin' && liSubTab === 'milestones');
      const onSliderCapableTab = (currentPhoneTab === 'jobs' || currentPhoneTab === 'a4' || isLiReviewMode || isLiConnMode || isLiMsMode);
      const isListMode = (currentPhoneTab === 'jobs' && jobsViewMode === 'list') || isLiReviewMode || isLiConnMode || isLiMsMode;
      const isAllowed = isSliderCurrentlyAllowed();
      const isListInactive = (currentPhoneTab === 'jobs' && jobsViewMode === 'list' && !activeListJobSno)
        || (isLiReviewMode && !activeLiPostId)
        || (isLiConnMode && !activeLiConnId)
        || (isLiMsMode && !activeLiMsId);
      pullTab.classList.toggle('list-mode-tab', isListMode);
      if (!onSliderCapableTab) {
        pullTab.style.display = 'none';
        return;
      }
      pullTab.textContent = currentPhoneTab === 'a4'
        ? '▶ JD & AI Rewrite'
        : (isLiReviewMode ? '▶ Post & AI Rewrite' : ((isLiConnMode || isLiMsMode) ? '▶ AI Rewrite' : '▶ JD & Referral'));
      if (isListInactive) {
        pullTab.style.display = 'flex';
        pullTab.style.opacity = '0.25';
