    function getUniqueLiLogs() {
      const raw = (liveState && (liveState.liLogs || liveState.linkedin)) || [];
      const seen = new Set();
      const out = [];
      for (let i = 0; i < raw.length; i++) {
        const item = raw[i];
        const id = String(item.activity_id || item.id || ('LI-' + (i + 1)));
        if (!seen.has(id)) {
          seen.add(id);
          out.push(item);
        }
      }
      return out;
    }

    function getUniqueFhContacts() {
      const raw = (liveState && (liveState.fhContacts || liveState.fhNetwork)) || [];
      const seen = new Set();
      const out = [];
      for (let i = 0; i < raw.length; i++) {
        const c = raw[i];
        const cid = String(c.contact_id || c.id || ('FH-' + (i + 1)));
        if (!seen.has(cid)) {
          seen.add(cid);
          if (!c.contact_id) c.contact_id = cid;
          if (!c.person_name && c.personName) c.person_name = c.personName;
          if (!c.company_name && c.company) c.company_name = c.company;
          if (!c.role_title && c.role) c.role_title = c.role;
          if (!c.target_profile_url && c.profileUrl) c.target_profile_url = c.profileUrl;
          if (!c.connection_note && c.icebreaker) c.connection_note = c.icebreaker;
          if (!c.approval_status && c.approvalStatus) c.approval_status = c.approvalStatus;
          out.push(c);
        }
      }
      return out;
    }

