    function isSameCompany(compA, compB) {
      const norm = (s) => String(s || '').toLowerCase()
        .replace(/\(.*?\)/g, '')
        .replace(/\b(inc|llc|ltd|limited|corp|corporation|company|co|group|india|global|technologies|technology|solutions|services|private|pvt|gsc|bcn|parthenon|airlines|bank)\b/g, '')
        .replace(/[^a-z0-9]+/g, ' ')
        .trim();
      const a = norm(compA);
      const b = norm(compB);
      if (!a || !b) return false;
      if (a === b) return true;
      const wordsA = a.split(/\s+/);
      const wordsB = b.split(/\s+/);
      if (wordsA[0] && wordsB[0] && wordsA[0] === wordsB[0] && wordsA[0].length >= 2) return true;
      return false;
    }

    let editingReferralState = null; // { sNo, idx, originalName, name, position, email, phone }

    function sanitizeReferralPosition(pos) {
      const p = String(pos || '').trim();
      if (!p) return '';
      if (/^(reference sheet insider|company referral|none|n\/a|-|—|null|undefined)$/i.test(p)) return '';
      if (/^(applied via referral|linkedin request sent)/i.test(p)) return '';
      return p;
    }

    function formatJobCardRefText(compRefs) {
      if (!Array.isArray(compRefs) || compRefs.length === 0) return 'None';
      if (compRefs.length === 1) return compRefs[0].name;
      if (compRefs.length === 2) return `${compRefs[0].name}, ${compRefs[1].name}`;
      return `${compRefs[0].name}, ${compRefs[1].name} and more`;
    }

    function getCompanyReferrals(j) {
      if (!j || !j.company) return [];
      const out = [];
      const seen = new Set();
      const pushSingleRef = (name, position, email, phone, source) => {
        const cleanName = String(name || '').trim();
        if (!cleanName || /^(none|assign|n\/a|-|—|null|undefined)$/i.test(cleanName)) return;
        const key = cleanName.toLowerCase();
        if (seen.has(key)) {
          const existing = out.find(x => x.name.toLowerCase() === key);
          if (existing) {
            const cleanPos = sanitizeReferralPosition(position);
            if (!existing.position && cleanPos) existing.position = cleanPos;
            if (!existing.email && email) existing.email = String(email).trim();
            if (!existing.phone && phone) existing.phone = String(phone).trim();
          }
          return;
        }
        seen.add(key);
        out.push({
          name: cleanName,
          position: sanitizeReferralPosition(position),
          email: String(email || '').trim(),
          phone: String(phone || '').trim(),
          source: source || 'Saved'
        });
      };
      const pushRef = (rawName, position, email, phone, source) => {
        const str = String(rawName || '').trim();
        if (!str) return;
        const parts = str.split(/[\/,]/).map(s => s.trim()).filter(Boolean);
        if (parts.length > 1) {
          parts.forEach((p, idx) => {
            pushSingleRef(p, idx === 0 ? position : '', idx === 0 ? email : '', idx === 0 ? phone : '', source);
          });
        } else {
          pushSingleRef(str, position, email, phone, source);
        }
      };
      const refContacts = (liveState && Array.isArray(liveState.refContacts)) ? liveState.refContacts : [];
      for (const rc of refContacts) {
        if (isSameCompany(j.company, rc.company_name)) {
          pushRef(
            rc.referrer_name,
            rc.position || rc.notes || '',
            rc.referrer_email || '',
            rc.referrer_phone || rc.phone || '',
            'Reference Vault'
          );
        }
      }
      if (j.reference && String(j.reference).trim()) {
        pushRef(
          j.reference,
          j.referralPosition || '',
          j.referralEmail || '',
          j.referralPhone || '',
          'Job Record'
        );
      }
      const allJobs = (liveState && Array.isArray(liveState.jobs)) ? liveState.jobs : [];
      for (const otherJob of allJobs) {
        if (otherJob && isSameCompany(j.company, otherJob.company) && otherJob.reference && String(otherJob.reference).trim()) {
          pushRef(
            otherJob.reference,
            otherJob.referralPosition || '',
            otherJob.referralEmail || '',
            otherJob.referralPhone || '',
            'Company Job Record'
          );
        }
      }
      return out;
    }

