                <option value="company_desc" ${jobSortBy==='company_desc'?'selected':''}>Company (Z → A)</option>
                <option value="pos_asc" ${jobSortBy==='pos_asc'?'selected':''}>Position (A → Z)</option>
                <option value="pos_desc" ${jobSortBy==='pos_desc'?'selected':''}>Position (Z → A)</option>
                <option value="match_desc" ${jobSortBy==='match_desc'?'selected':''}>Match Score (High → Low)</option>
              </select>
            </div>
          </div>
        </div>
        </div>
      `;

      if (filtered.length === 0) {
        body.innerHTML = topBarHtml + `
          <div class="m-card" style="text-align:center;padding:30px 14px;">
            <div style="font-size:24px;margin-bottom:6px;">🔍</div>
            <div style="font-size:12px;font-weight:800;">No jobs match current filters</div>
            <button class="m-btn m-btn-primary mt-2" onclick="resetJobFilters()">Reset All Filters</button>
          </div>
