        return;
      }

      const formatPortalDisplay = (p) => {
        const raw = String(p || 'Company site').trim();
        if (/company\s*career\s*site|company\s*site/i.test(raw)) return 'Company site';
        return raw.replace(/^⏳\s*Queued\s*\((.*)\)$/i, '$1').replace(/^⚡\s*In-Portal Easy Apply\s*\((.*)\)$/i, '$1').trim() || 'Company site';
      };

      const getJobCardColorStyle = (jobItem) => {
        const stRaw = String((jobItem && jobItem.status) || '') + ' ' + String((jobItem && jobItem.stageBucket) || '');
        if (/approved|applied|submitted|interview|offer/i.test(stRaw)) {
          return 'border: 2px solid #10b981 !important; background: linear-gradient(145deg, rgba(16, 185, 129, 0.22) 0%, rgba(16, 185, 129, 0.08) 50%, var(--bg-surface) 100%) !important; box-shadow: 0 12px 30px rgba(16, 185, 129, 0.18);';
        }
        if (/declined|rejected|hold|skip|pass/i.test(stRaw)) {
          return 'border: 2px solid #ef4444 !important; background: linear-gradient(145deg, rgba(239, 68, 68, 0.22) 0%, rgba(239, 68, 68, 0.08) 50%, var(--bg-surface) 100%) !important; box-shadow: 0 12px 30px rgba(239, 68, 68, 0.18);';
        }
        return 'border: 2px solid #eab308 !important; background: linear-gradient(145deg, rgba(234, 179, 8, 0.22) 0%, rgba(234, 179, 8, 0.08) 50%, var(--bg-surface) 100%) !important; box-shadow: 0 12px 30px rgba(234, 179, 8, 0.18);';
      };

      if (jobsViewMode === 'swipe') {
        if (swipeCursor >= filtered.length) swipeCursor = Math.max(0, filtered.length - 1);
        if (swipeCursor < 0) swipeCursor = 0;
        const isFirstCard = swipeCursor <= 0;
        const isLastCard = swipeCursor >= filtered.length - 1;
        const disabledNavStyle = 'opacity:0.32;color:#64748b !important;border-color:#334155 !important;background:rgba(15,23,42,0.5) !important;cursor:not-allowed !important;pointer-events:none !important;box-shadow:none !important;transform:none !important;';
        const j = filtered[swipeCursor] || filtered[0];
        selectedJobSno = String(j.sNo);
        const rel = computeJdRelevanceBreakdown(j);
        const portalDisplay = formatPortalDisplay(j.portal);
        const compRefs = getCompanyReferrals(j);
        const refDisplay = formatJobCardRefText(compRefs);
        const cardColorStyle = getJobCardColorStyle(j);

        body.innerHTML = topBarHtml + `
          <!-- Card Counter -->
          <div style="display:flex;justify-content:space-between;align-items:center;font-size:10px;color:var(--text-muted);margin-bottom:6px;padding:0 2px;">
            <span>Card <strong>${swipeCursor + 1}</strong> of <strong>${filtered.length}</strong></span>
          </div>

          <!-- 2.4 INTERACTIVE SWIPE CARD STACK -->
          <div class="swipe-stage">
            <div class="swipe-card-bg2"></div>
            <div class="swipe-card-bg1"></div>
            <div class="swipe-card" id="active-swipe-card" style="${cardColorStyle}" onclick="inspectJobWithoutTabChange('${j.sNo}')">
              <div id="stamp-approve" class="swipe-stamp approve">APPROVE 💚</div>
              <div id="stamp-nope" class="swipe-stamp nope">PASS ❌</div>

              <!-- Company, Hyperlinked Position, Job ID, Location & Portal -->
              <div style="margin-bottom:10px;min-width:0;overflow:hidden;">
                <div style="font-size:15px;font-weight:800;line-height:1.2;white-space:normal;overflow-wrap:anywhere;word-break:break-word;">${escH(j.company)}</div>
                <div style="font-size:13px;font-weight:800;color:var(--accent);margin-top:3px;line-height:1.28;white-space:normal;overflow-wrap:anywhere;word-break:break-word;">
                  ${(j.jdUrl || j.jobUrl) ? `<a href="${escH(j.jdUrl || j.jobUrl)}" target="_blank" rel="noopener noreferrer" onclick="event.stopPropagation();" onpointerdown="event.stopPropagation();" style="color:var(--accent);text-decoration:underline;text-underline-offset:2px;" title="Open original job posting">${escH(j.role || j.title)}</a>` : escH(j.role || j.title)}
                </div>
                <div style="font-size:10px;font-weight:700;color:var(--text-secondary);margin-top:3px;">
                  Job ID: <span style="font-family:monospace;color:var(--text-main);">${escH(formatJobIdDisplay(j))}</span>
                </div>
                <div style="font-size:10px;color:var(--text-muted);margin-top:3px;">
                  <i class="bi bi-geo-alt-fill text-danger"></i> ${escH(j.location || 'Remote / India')}
                </div>
                <div style="font-size:10px;color:var(--text-muted);margin-top:2px;">
                  🌐 ${escH(portalDisplay)}
                </div>
              </div>

              <!-- Matched & Missing JD Keyword Pills -->
              <div style="display:flex;flex-wrap:wrap;gap:4px;margin-bottom:6px;">
                ${rel.matched.slice(0, 3).map(kw => `<span style="font-size:9px;padding:2px 6px;border-radius:6px;background:var(--success-soft);color:var(--success);font-weight:700;">${escH(kw)}</span>`).join('')}
                ${rel.missing.slice(0, 1).map(kw => `<span style="font-size:9px;padding:2px 6px;border-radius:6px;background:var(--warning-soft);color:var(--warning);font-weight:700;">${escH(kw)}</span>`).join('')}
              </div>

              <!-- Referral Row -->
              <div style="margin-bottom:8px;">
                <button type="button" onpointerdown="event.stopPropagation();" onclick="event.stopPropagation();selectedJobSno='${j.sNo}';sliderTab='referral';setSliderState('open');renderHalfSlider();" style="cursor:pointer;display:inline-block;font-size:9.5px;padding:3px 8px;border-radius:6px;background:var(--primary-soft);color:var(--primary);font-weight:700;border:1px solid rgba(99,102,241,0.3);min-height:24px;" title="Tap to view or add referral for ${escH(j.company)}">🤝 Ref: ${escH(refDisplay)}</button>
              </div>

              <!-- CV %, CL % & Boost Button Row (Just Below Ref) -->
              <div style="display:flex;align-items:center;gap:6px;flex-wrap:wrap;">
                <button type="button" onpointerdown="event.stopPropagation();" onclick="event.stopPropagation();openJobDocumentView('${j.sNo}', 'resume');" style="cursor:pointer;display:inline-flex;align-items:center;padding:4px 8px;border-radius:7px;font-size:10px;font-weight:800;background:var(--success-soft);color:var(--success);border:1px solid rgba(16,185,129,0.35);min-height:26px;" title="Tap to open Resume view">
                  📄 CV ${rel.resumeScore}%
                </button>
                <button type="button" onpointerdown="event.stopPropagation();" onclick="event.stopPropagation();openJobDocumentView('${j.sNo}', 'cl');" style="cursor:pointer;display:inline-flex;align-items:center;padding:4px 8px;border-radius:7px;font-size:10px;font-weight:800;background:var(--primary-soft);color:var(--primary);border:1px solid rgba(99,102,241,0.35);min-height:26px;" title="Tap to open Cover Letter view">
                  ✉️ CL ${rel.clScore}%
                </button>
                <button type="button" onpointerdown="event.stopPropagation();" onclick="event.stopPropagation();openBoostModal('${j.sNo}');" style="cursor:pointer;display:inline-flex;align-items:center;padding:4px 10px;border-radius:7px;font-size:10px;font-weight:800;background:var(--bg-surface-2);color:var(--accent);border:1px solid rgba(56,189,248,0.45);min-height:26px;" title="Open Boost options">
                  🚀 Boost
                </button>
              </div>
            </div>
          </div>

          <!-- SWIPE DECK ACTION DOCK -->
          <div class="swipe-dock">
            <button class="swipe-fab info" ${isFirstCard ? 'disabled' : ''} style="${isFirstCard ? disabledNavStyle : ''}" onclick="if(!${isFirstCard}) navigateDeckCard(-1)" title="${isFirstCard ? 'First Job Opening' : 'Previous Job Opening'}">
              <i class="bi bi-arrow-left"></i>
            </button>
            <button class="swipe-fab pass" onclick="triggerDeckSwipe('left', '${j.sNo}')" title="Reject Job (Turns Card Red)">
              <i class="bi bi-x-lg"></i>
            </button>
            <button class="swipe-fab like" onclick="triggerDeckSwipe('right', '${j.sNo}')" title="Accept / Approve Job (Turns Card Green)">
              <i class="bi bi-heart-fill"></i>
            </button>
            <button class="swipe-fab super" style="color:#f59e0b;border-color:rgba(245,158,11,0.5);" onclick="triggerDeckSwipe('auto_apply', '${j.sNo}')" title="Apply Now (Immediate Application)">
              <i class="bi bi-lightning-charge-fill"></i>
            </button>
            <button class="swipe-fab info" ${isLastCard ? 'disabled' : ''} style="${isLastCard ? disabledNavStyle : ''}" onclick="if(!${isLastCard}) navigateDeckCard(1)" title="${isLastCard ? 'Last Job Opening' : 'Next Job Opening'}">
              <i class="bi bi-arrow-right"></i>
            </button>
          </div>
        `;
        setTimeout(attachSwipeTouchHandlers, 20);
      } else {
        // COMPACT LIST VIEW (All items rendered in original order; single active card selection + bold active border)
        const prevListScrollTop = body.scrollTop || 0;
        if (activeListJobSno) {
          selectedJobSno = String(activeListJobSno);
        }
        body.innerHTML = topBarHtml + `
          ${filtered.map(j => {
            const rel = computeJdRelevanceBreakdown(j);
            const rowColorStyle = getJobCardColorStyle(j);
            const isCardActive = String(activeListJobSno || '') === String(j.sNo);
            const activeBorderStyle = isCardActive
              ? 'border-width: 4px !important; box-shadow: 0 0 0 2px rgba(255, 255, 255, 0.92), 0 10px 26px rgba(0, 0, 0, 0.65) !important;'
              : 'border-width: 1.5px !important;';
            return `
              <div id="job-list-card-${j.sNo}" data-sno="${j.sNo}" class="m-card ${isCardActive ? 'list-card-active' : ''}" onclick="selectListJobCard('${j.sNo}')" style="cursor:pointer;transition:box-shadow 0.15s ease, border-width 0.12s ease;${rowColorStyle}${activeBorderStyle}">
                <div style="display:flex;justify-content:space-between;align-items:flex-start;gap:8px;">
                  <div style="min-width:0;flex:1;">
                    <div style="font-size:12px;font-weight:800;">${escH(j.company)}</div>
                    <div style="font-size:11px;color:var(--accent);font-weight:700;margin-top:2px;">${(j.jdUrl || j.jobUrl) ? `<a href="${escH(j.jdUrl || j.jobUrl)}" target="_blank" rel="noopener noreferrer" onclick="event.stopPropagation();" style="color:var(--accent);text-decoration:underline;">${escH(j.role || j.title)}</a>` : escH(j.role || j.title)}</div>
                    <div style="font-size:9.5px;color:var(--text-secondary);font-weight:700;margin-top:2px;font-family:monospace;">${escH(formatJobIdDisplay(j))}</div>
                    <div style="font-size:9.5px;color:var(--text-muted);margin-top:4px;">
                      <i class="bi bi-geo-alt-fill text-danger"></i> ${escH(j.location || 'Remote')}
                    </div>
                    <div style="font-size:9.5px;color:var(--text-muted);margin-top:2px;">
                      🌐 ${escH(formatPortalDisplay(j.portal))}
                    </div>
                  </div>
                  <div style="display:flex;flex-direction:column;align-items:flex-end;gap:6px;flex-shrink:0;">
                    <div style="display:flex;gap:4px;align-items:center;">
                      <button type="button" onclick="event.stopPropagation();openJobDocumentView('${j.sNo}', 'resume');" style="cursor:pointer;font-size:9px;padding:3px 7px;border-radius:6px;background:var(--success-soft);color:var(--success);font-weight:800;border:1px solid rgba(16,185,129,0.35);min-height:24px;">CV ${rel.resumeScore}%</button>
                      <button type="button" onclick="event.stopPropagation();openJobDocumentView('${j.sNo}', 'cl');" style="cursor:pointer;font-size:9px;padding:3px 7px;border-radius:6px;background:var(--primary-soft);color:var(--primary);font-weight:800;border:1px solid rgba(99,102,241,0.35);min-height:24px;">CL ${rel.clScore}%</button>
                    </div>
                    <div style="display:flex;gap:6px;align-items:center;justify-content:flex-end;width:100%;">
                      <button type="button" onclick="event.stopPropagation();triggerDeckSwipe('left', '${j.sNo}');" style="cursor:pointer;flex:1;display:inline-flex;align-items:center;justify-content:center;font-size:11px;font-weight:900;padding:3px 8px;border-radius:6px;background:rgba(239,68,68,0.16);color:#ef4444;border:1px solid rgba(239,68,68,0.45);min-height:24px;" title="Reject Job">✕</button>
                      <button type="button" onclick="event.stopPropagation();triggerDeckSwipe('right', '${j.sNo}');" style="cursor:pointer;flex:1;display:inline-flex;align-items:center;justify-content:center;font-size:11px;font-weight:900;padding:3px 8px;border-radius:6px;background:rgba(16,185,129,0.16);color:#10b981;border:1px solid rgba(16,185,129,0.45);min-height:24px;" title="Approve Job">✓</button>
                    </div>
                  </div>
                </div>
              </div>
            `;
          }).join('')}
        `;
        if (window._pendingScrollToListSno) {
          const targetSno = window._pendingScrollToListSno;
          window._pendingScrollToListSno = null;
          scrollJobListItemToTop(targetSno);
        } else if (prevListScrollTop > 0) {
          body.scrollTop = prevListScrollTop;
        }
      }
    }

    function attachSwipeTouchHandlers() {
      const card = document.getElementById('active-swipe-card');
      if (!card) return;
      let startX = 0, currentX = 0, dragging = false;
      const stampApprove = document.getElementById('stamp-approve');
      const stampNope = document.getElementById('stamp-nope');

      const onDown = (e) => {
        if (e.target.closest('button, select, option, a')) return;
        dragging = true;
        startX = e.clientX || (e.touches && e.touches[0].clientX) || 0;
        currentX = startX;
        card.style.transition = 'none';
      };
      const onMove = (e) => {
        if (!dragging) return;
        currentX = e.clientX || (e.touches && e.touches[0].clientX) || startX;
        const dx = currentX - startX;
        const rot = dx * 0.06;
        card.style.transform = `translate3d(${dx}px, 0, 0) rotate(${rot}deg)`;
        if (stampApprove) stampApprove.style.opacity = dx > 25 ? Math.min(1, (dx - 25) / 70) : 0;
        if (stampNope) stampNope.style.opacity = dx < -25 ? Math.min(1, (-dx - 25) / 70) : 0;
      };
      const onUp = () => {
        if (!dragging) return;
        dragging = false;
        const dx = currentX - startX;
        card.style.transition = 'transform 0.28s cubic-bezier(0.22, 1, 0.36, 1), opacity 0.25s ease';
        if (dx > 85) {
          triggerDeckSwipe('right', selectedJobSno);
        } else if (dx < -85) {
          triggerDeckSwipe('left', selectedJobSno);
        } else {
          card.style.transform = '';
          if (stampApprove) stampApprove.style.opacity = 0;
          if (stampNope) stampNope.style.opacity = 0;
        }
      };

      card.addEventListener('pointerdown', onDown);
      window.addEventListener('pointermove', onMove);
      window.addEventListener('pointerup', onUp);
    }

    // =========================================================================
    // CANDIDATE APPLICATION SIGN-OFF & NON-MISREPRESENTATION CONTROLLER
    // =========================================================================
    let pendingSignoffContext = null; // { sNo, targetStatus, fromSwipeDir }

    function openCandidateSignoffModal(sNo, targetStatus, fromSwipeDir) {
      const jobs = (liveState && liveState.jobs) || [];
      const job = jobs.find(j => String(j.sNo) === String(sNo)) || getSelectedJob();
      pendingSignoffContext = { sNo: String(job.sNo || sNo), targetStatus: targetStatus || 'Approved', fromSwipeDir: fromSwipeDir || null };
      const lbl = document.getElementById('signoff-modal-job-label');
      if (lbl) lbl.textContent = `#${job.sNo} ${job.company || 'Company'} — ${job.role || job.title || 'Target Role'}`;
      const chk = document.getElementById('signoff-modal-checkbox');
      if (chk) chk.checked = Boolean(job._signedOff);
      const modal = document.getElementById('signoff-modal-backdrop');
      if (modal) modal.style.display = 'flex';
      toggleSignoffConfirmBtn();
    }

    function closeCandidateSignoffModal() {
      const modal = document.getElementById('signoff-modal-backdrop');
      if (modal) modal.style.display = 'none';
      pendingSignoffContext = null;
      renderSimulator();
    }

    function toggleSignoffConfirmBtn() {
      const chk = document.getElementById('signoff-modal-checkbox');
      const btn = document.getElementById('signoff-confirm-btn');
      if (!btn) return;
      btn.style.opacity = (chk && chk.checked) ? '1' : '0.55';
    }

    let showA4EditDrawer = false;

    function editResumeBeforeSignoff() {
      const ctx = pendingSignoffContext;
      closeCandidateSignoffModal();
      if (ctx && ctx.sNo) selectedJobSno = String(ctx.sNo);
      if (currentPhoneTab === 'jobs') {
        sliderTab = 'ai';
        setSliderState('half');
      } else {
        showA4EditDrawer = true;
        setPhoneTab('a4');
      }
      notifyToast('Review and modify your Resume & Cover Letter before signing off.');
    }

    function confirmCandidateSignoff() {
      const chk = document.getElementById('signoff-modal-checkbox');
      if (!chk || !chk.checked) {
        notifyToast('Please check the Candidate Sign-Off box to confirm you read the JD and approve the Resume & Cover Letter.');
        return;
      }
      const ctx = pendingSignoffContext || { sNo: selectedJobSno, targetStatus: 'Approved', fromSwipeDir: null };
      const jobs = (liveState && liveState.jobs) || [];
      const job = jobs.find(j => String(j.sNo) === String(ctx.sNo)) || getSelectedJob();
      job._signedOff = true;
      job._signedOffAt = new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
      const modal = document.getElementById('signoff-modal-backdrop');
      if (modal) modal.style.display = 'none';
      pendingSignoffContext = null;

      if (ctx.fromSwipeDir) {
        executeDeckSwipeAfterSignoff(ctx.fromSwipeDir, ctx.sNo);
      } else {
        applyJobStatusWithSignoff(ctx.sNo, ctx.targetStatus);
      }
    }

    function approveFromA4WithSignoff(sNo, targetStatus) {
      const jobs = (liveState && liveState.jobs) || [];
      const job = jobs.find(j => String(j.sNo) === String(sNo)) || getSelectedJob();
      const chk = document.getElementById('a4-signoff-chk');
      if (!job._signedOff && (!chk || !chk.checked)) {
        openCandidateSignoffModal(sNo, targetStatus || 'Approved', null);
        return;
      }
      job._signedOff = true;
      job._signedOffAt = job._signedOffAt || new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
      applyJobStatusWithSignoff(sNo, targetStatus || 'Approved');
    }

    async function navigateDeckCard(delta) {
      const filtered = getFilteredSortedJobs();
      if (!filtered.length) return;
      const nextIdx = swipeCursor + delta;
      if (nextIdx < 0 || nextIdx >= filtered.length) return;
      swipeCursor = nextIdx;
      if (filtered[swipeCursor]) selectedJobSno = String(filtered[swipeCursor].sNo);
      renderSimulator();
      if (sliderState !== 'closed') renderHalfSlider();
    }

    function undoDeckSwipe() {
      navigateDeckCard(-1);
    }

    function triggerDeckSwipe(dir, sNo) {
      executeDeckSwipeAfterSignoff(dir, sNo);
    }

    async function executeDeckSwipeAfterSignoff(dir, sNo) {
      const filtered = getFilteredSortedJobs();
      const idx = filtered.findIndex(j => String(j.sNo) === String(sNo));
      if (idx >= 0) {
        swipeCursor = idx;
        selectedJobSno = String(sNo);
      }
      const job = (idx >= 0 ? filtered[idx] : null) || getSelectedJob();
      if (!job) return;

      if (dir === 'right') {
        job._signedOff = true;
        job.status = 'Approved';
        job.stageBucket = 'Approved';
        notifyToast(`💚 Accepted #${job.sNo} ${job.company} — Queued for Apply after review!`);
        callBackendJobAction(job.sNo, 'approve', { status: 'Approved', candidateSignedOff: true });
      } else if (dir === 'auto_apply') {
        job._signedOff = true;
        job.status = 'Applied';
        job.stageBucket = 'Applied';
        job.appliedOn = job.appliedOn || 'Today';
        notifyToast(`⚡ Applying Now to #${job.sNo} ${job.company}!`);
        callBackendJobAction(job.sNo, 'apply_now', { status: 'Applied', applyImmediately: true, candidateSignedOff: true });
      } else {
        job.status = 'Rejected';
        job.stageBucket = 'Rejected';
        notifyToast(`❌ Rejected #${job.sNo} ${job.company}`);
