    function measureFullPdfOnePageFit() {
      const stage = document.getElementById('cp-a4-stage');
      const holder = document.getElementById('cp-a4-holder');
      const scaler = document.getElementById('cp-a4-scaler');
      const sheet = document.getElementById('cp-true-a4-sheet');
      const inner = document.getElementById('cp-true-a4-inner');
      const marginGuide = document.getElementById('cp-a4-margin-guide');
      const badge = document.getElementById('cp-a4-fit-badge');
      if (!sheet) return;

      // 1. Collapse holder momentarily so flex child never stretches stage width/height on Android
      if (stage && holder && scaler) {
        holder.style.width = '0px';
        holder.style.height = '0px';
        const modalCard = stage.parentElement;
        const rawStageW = stage.clientWidth || (modalCard ? modalCard.clientWidth - 20 : 0) || ((window.innerWidth || 360) - 32);
        const availW = Math.max(190, Math.min(rawStageW - 12, (window.innerWidth || 360) - 34));
        const headerOffset = stage.offsetTop || 118;
        const maxModalH = Math.floor((window.innerHeight || 680) * 0.94);
        const availH = Math.max(230, maxModalH - headerOffset - 22);
        const scaleW = availW / 794;
        const scaleH = availH / 1123;
        const scaleFactor = Math.max(0.20, Math.min(scaleW, scaleH));
        holder.style.width = Math.floor(794 * scaleFactor) + 'px';
        holder.style.height = Math.floor(1123 * scaleFactor) + 'px';
        scaler.style.transform = `scale(${scaleFactor})`;
      }

      // 2. Auto-fit all document sections strictly inside the printable A4 area (1123 - top/bottom margins)
      const maxH = 1123;
      const topBottomPad = 32;
      const leftRightPad = 38;
      const availInnerH = maxH - (topBottomPad * 2); // 1059px printable height inside margins

      if (marginGuide) {
        marginGuide.style.top = topBottomPad + 'px';
        marginGuide.style.bottom = topBottomPad + 'px';
        marginGuide.style.left = leftRightPad + 'px';
        marginGuide.style.right = leftRightPad + 'px';
      }

      sheet.style.padding = `${topBottomPad}px ${leftRightPad}px`;
      sheet.style.fontSize = '12.6px';
      sheet.style.lineHeight = '1.28';

      let finalVisualInnerH = availInnerH;
      if (inner) {
        inner.style.display = 'flow-root';
        inner.style.transformOrigin = 'top left';
        inner.style.transform = 'none';
        inner.style.width = '100%';

        // Step 2a: Try smooth font-size stepping first (12.6px -> 9.5px)
        for (let px = 12.6; px >= 9.5; px -= 0.3) {
          const lh = Number((1.16 + ((px - 9.5) / 3.1) * 0.12).toFixed(2));
          sheet.style.fontSize = px.toFixed(2) + 'px';
          sheet.style.lineHeight = String(lh);
          if (inner.offsetHeight <= availInnerH) {
            break;
          }
        }

        // Step 2b: GPU-enforced 2D proportional fit (width: 100/s % + scale(s))
        // Works on all Android devices even when system minimum font-size / font-boosting is active!
        if (inner.offsetHeight > availInnerH) {
          for (let s = 0.98; s >= 0.42; s -= 0.02) {
            const sc = Number(s.toFixed(3));
            inner.style.width = (100 / sc).toFixed(2) + '%';
            inner.style.transform = `scale(${sc})`;
            if (inner.offsetHeight * sc <= availInnerH) {
              finalVisualInnerH = Math.round(inner.offsetHeight * sc);
              break;
            }
          }
        } else {
          finalVisualInnerH = inner.offsetHeight;
        }
      }

      const pct = Math.min(100, Math.max(70, Math.round(((finalVisualInnerH + topBottomPad * 2) / maxH) * 100)));
      if (badge) {
        badge.style.background = 'rgba(16,185,129,0.2)';
        badge.style.color = '#10b981';
        badge.style.borderColor = 'rgba(16,185,129,0.45)';
        badge.textContent = `✅ Fits 1 Page (${pct}% of A4)`;
      }
    }

