    function returnToJobCardFromDoc(sNo) {
      selectedJobSno = String(sNo);
      jobsViewMode = window._lastJobsViewModeBeforeDoc || jobsViewMode || 'swipe';
      let filtered = getFilteredSortedJobs();
      let idx = filtered.findIndex(item => String(item.sNo) === String(sNo));
      if (idx < 0) {
        jobFilterCompany = 'ALL';
        jobFilterPosition = 'ALL';
        jobFilterStatus = 'ALL';
        jobSearchQuery = '';
        filtered = getFilteredSortedJobs();
        idx = filtered.findIndex(item => String(item.sNo) === String(sNo));
      }
      if (idx >= 0) swipeCursor = idx;
      window._pendingScrollToListSno = String(sNo);
