    function buildCuratedReferralOutreachPayload(j, refContact) {
      const firstName = String(refContact?.name || 'there').trim().split(/\s+/)[0] || 'there';
      const roleTitle = String(j?.role || j?.title || 'Analytics Role').trim();
      const companyName = String(j?.company || 'your organization').trim();
      const jobIdStr = formatJobIdDisplay(j);
      const jobUrl = String(j?.jdUrl || j?.jobUrl || '').trim();
      const cvUrl = String(j?.resumeUrl || j?.resumeLink || (j?.resumeDriveId ? `https://drive.google.com/file/d/${j.resumeDriveId}/view?usp=sharing` : '')).trim();
      const clUrl = String(j?.clUrl || j?.clLink || (j?.clDriveId ? `https://drive.google.com/file/d/${j.clDriveId}/view?usp=sharing` : '')).trim();
      const fullJd = getFullVerbatimJdText(j);
      const jdExcerpt = fullJd.length > 1200 ? (fullJd.slice(0, 1200) + '...') : fullJd;

      const subject = `Referral Request: ${roleTitle} (Job ID: ${jobIdStr}) — ${companyName} | Sumanto Banerjee`;

      const lines = [
        `Hi ${firstName},`,
        ``,
        `I hope you are doing well! I was hoping you might be open to referring me for the ${roleTitle} position at ${companyName} (Job ID: ${jobIdStr}).`,
        ``,
        `Given my experience in SQL, Python, Tableau, and enterprise business analytics, I believe my background aligns strongly with the team's requirements. For your convenience, I have shared my tailored CV, Cover Letter, and the Job Description details below:`,
        ``,
        `• Position: ${roleTitle}`,
        `• Company: ${companyName}`,
        `• Job ID: ${jobIdStr}`
      ];
      if (jobUrl) lines.push(`• Job Posting: ${jobUrl}`);
      if (cvUrl) lines.push(`• Tailored CV (PDF): ${cvUrl}`);
      if (clUrl) lines.push(`• Cover Letter (PDF): ${clUrl}`);
      lines.push(
        ``,
        `--- Job Description ---`,
        jdExcerpt,
        ``,
        `Thank you so much for your time and support!`,
        ``,
        `Warm regards,`,
        `Sumanto Banerjee`,
        `+91 96504 26526 | user@example.com`
      );

      return {
        subject,
        body: lines.join('\n')
      };
    }

    function sendReferralWhatsApp(sNo, idx) {
      const j = getSelectedJob();
      const compRefs = getCompanyReferrals(j);
      const r = compRefs[idx];
      if (!r || !r.phone) {
        notifyToast('⚠️ No contact number available for this referral.');
        return;
      }
