                            <button type="button" class="m-btn m-btn-primary" style="padding:2px 8px;font-size:9px;font-weight:800;border-radius:6px;min-height:22px;flex-shrink:0;" onclick="event.stopPropagation();sendReferralGmail('${j.sNo}', ${idx})" title="Open Gmail with drafted subject, CV, CL, JD & Job ID ready to send">
                              <i class="bi bi-envelope-fill"></i> Gmail
                            </button>
                          </div>
                        ` : ''}
                        ${!hasExtraDetails ? `
                          <div style="font-size:9px;color:var(--text-muted);">No position, phone, or email saved yet. Tap ✏️ to add details.</div>
                        ` : ''}
                      </div>
                    ` : ''}
                  </div>
                `;
              }).join('') : `
                <div style="background:var(--bg-surface-2);border:1px dashed var(--border-color);border-radius:8px;padding:8px;color:var(--text-muted);text-align:center;font-size:9.5px;">
                  No references available for <strong>${escH(j.company)}</strong> yet (Ref: None).
                </div>
              `}
            </div>

            <div style="background:var(--bg-surface);border:1px solid ${isEditingThisJob ? 'var(--primary)' : 'var(--border-color)'};border-radius:10px;padding:8px;font-size:10px;">
              <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:6px;gap:6px;">
                <span style="font-weight:800;color:var(--primary);">${isEditingThisJob ? '✏️ Edit Referral' : 'Add Referral'} for ${escH(j.company)}</span>
                <div style="display:flex;align-items:center;gap:4px;flex-shrink:0;">
                  <button class="m-btn m-btn-primary" style="padding:2px 8px;font-size:12px;font-weight:900;border-radius:6px;min-height:24px;line-height:1;" onclick="pickReferralFromContactList('${j.sNo}')" title="Add contact from Contact List">+</button>
                  ${isEditingThisJob ? `<button class="m-btn m-btn-ghost" style="padding:1px 6px;font-size:9px;min-height:20px;" onclick="cancelEditSliderReferral()">Cancel</button>` : ''}
                </div>
              </div>
              <input type="file" id="sl-ref-vcf-input" accept=".vcf,text/vcard,text/x-vcard" style="display:none;" onchange="handleReferralVcfFile(this)" />
              <div id="sl-contact-picker-drawer" style="display:${window._showSliderContactPicker ? 'block' : 'none'};background:var(--bg-surface-2);border:1px solid var(--primary);border-radius:8px;padding:6px;margin-bottom:7px;">
                <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:4px;">
                  <span style="font-weight:800;font-size:9.5px;color:var(--primary);">📒 Select from Contact List</span>
                  <div style="display:flex;gap:4px;">
                    <button class="m-btn m-btn-ghost" style="padding:1px 6px;font-size:8.5px;min-height:18px;" onclick="document.getElementById('sl-ref-vcf-input')?.click()">📱 .vcf</button>
                    <button class="m-btn m-btn-ghost" style="padding:1px 5px;font-size:8.5px;min-height:18px;" onclick="window._showSliderContactPicker=false;renderHalfSlider();">✕</button>
                  </div>
                </div>
                <input id="sl-contact-picker-search" class="m-input mb-1" style="font-size:9.5px;padding:4px 6px;" placeholder="Search contact name, role, company..." oninput="filterSliderContactPickerList(this.value)" />
                <div id="sl-contact-picker-list" style="max-height:135px;overflow-y:auto;display:flex;flex-direction:column;gap:4px;">
                  ${renderSliderContactPickerItems(j, '')}
                </div>
              </div>
              <input id="sl-ref-name" class="m-input mb-2" placeholder="Name *" value="${escH(editName)}" />
              <input id="sl-ref-position" class="m-input mb-2" placeholder="Position" value="${escH(editPos)}" />
              <input id="sl-ref-email" type="email" class="m-input mb-2" placeholder="Email" value="${escH(editEmail)}" />
              <input id="sl-ref-phone" type="tel" class="m-input mb-2" placeholder="Contact number" value="${escH(editPhone)}" />
              <button class="m-btn m-btn-success w-100" onclick="saveSliderReferral('${j.sNo}')">${isEditingThisJob ? 'Save Changes' : ('💾 Save Referral for ' + escH(j.company))}</button>
            </div>
          `;
        })() : ''}
      `;
    }

    function parseContactNameAndPosition(rawName, explicitPos, companyHint) {
      let name = String(rawName || '').trim();
      let pos = sanitizeReferralPosition(explicitPos || '');
      if (!name) return { name: '', position: pos };

      // Extract parenthetical role e.g. "Avneet Singh (Manager Data Science)"
      const parenMatch = name.match(/^([^()]+)\(([^()]+)\)$/);
      if (parenMatch) {
        const mainPart = parenMatch[1].trim();
        const insidePart = parenMatch[2].trim();
        if (mainPart && insidePart && !pos) {
          name = mainPart;
          pos = insidePart;
        }
      }

      // Extract dash / pipe / comma role e.g. "Avneet Singh - Manager Data Science"
      const sepMatch = name.match(/^(.+?)\s+(?:—|–|-|\|)\s+(.+)$/);
      if (sepMatch) {
        const left = sepMatch[1].trim();
        const right = sepMatch[2].trim();
        if (left && right && !pos) {
          name = left;
          pos = right;
        }
      }

      // Strip trailing "@ Company" or "- Company" from position if identical to companyHint
      if (pos && companyHint) {
        const compClean = String(companyHint).trim().replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
        pos = pos.replace(new RegExp('(?:\\s*[@|—–-]\\s*|\\s+at\\s+)' + compClean + '$', 'i'), '').trim();
      }

      // If position still empty, check if this person is in liveState.fhContacts or liveState.refContacts
      if (!pos && typeof liveState === 'object' && liveState) {
        const lowerName = name.toLowerCase();
        const fhMatch = (liveState.fhContacts || []).find(c => String(c.person_name || '').toLowerCase().trim() === lowerName);
        if (fhMatch && fhMatch.role_title) {
          pos = sanitizeReferralPosition(fhMatch.role_title);
        }
      }

      return { name, position: pos };
    }

    function applyPickedContactToReferralInputs(contactObj) {
      const j = getSelectedJob();
      const parsed = parseContactNameAndPosition(contactObj.name, contactObj.position, j?.company);
      const email = String(contactObj.email || '').trim();
      const phone = String(contactObj.phone || '').trim();

      const nameEl = document.getElementById('sl-ref-name');
      const posEl = document.getElementById('sl-ref-position');
      const emailEl = document.getElementById('sl-ref-email');
      const phoneEl = document.getElementById('sl-ref-phone');

      if (nameEl) nameEl.value = parsed.name || '';
      if (posEl) posEl.value = parsed.position || '';
      if (emailEl) emailEl.value = email;
      if (phoneEl) phoneEl.value = phone;

      const drawer = document.getElementById('sl-contact-picker-drawer');
      if (drawer) drawer.style.display = 'none';
      window._showSliderContactPicker = false;
      notifyToast(`✅ Populated ${parsed.name || 'contact'} details!`);
    }

    function getAllPickableContactsForJob(j) {
      const list = [];
      const seen = new Set();
      const addEntry = (name, position, email, phone, company) => {
        const cleanName = String(name || '').trim();
        if (!cleanName || /^(none|assign|n\/a|-|—|null|undefined)$/i.test(cleanName)) return;
        const key = (cleanName + '|' + String(company || '')).toLowerCase();
        if (seen.has(key)) return;
        seen.add(key);
        list.push({
          name: cleanName,
          position: sanitizeReferralPosition(position),
          email: String(email || '').trim(),
          phone: String(phone || '').trim(),
          company: String(company || '').trim(),
          isTargetCompany: Boolean(j && j.company && isSameCompany(j.company, company))
        });
      };

      for (const c of (liveState?.fhContacts || [])) {
        addEntry(c.person_name, c.role_title || '', c.email || '', c.phone || '', c.company_name || '');
      }
      for (const rc of (liveState?.refContacts || [])) {
        addEntry(rc.referrer_name, rc.position || rc.notes || '', rc.referrer_email || '', rc.referrer_phone || rc.phone || '', rc.company_name || '');
      }

      list.sort((a, b) => {
        if (a.isTargetCompany !== b.isTargetCompany) return a.isTargetCompany ? -1 : 1;
        return a.name.localeCompare(b.name);
      });
      return list;
    }

    function renderSliderContactPickerItems(j, query) {
      const q = String(query || '').toLowerCase().trim();
      const all = getAllPickableContactsForJob(j).filter(c => {
        if (!q) return true;
        return (
          c.name.toLowerCase().includes(q) ||
          c.position.toLowerCase().includes(q) ||
          c.company.toLowerCase().includes(q) ||
          c.email.toLowerCase().includes(q) ||
          c.phone.toLowerCase().includes(q)
        );
      });
      if (all.length === 0) {
        return `<div style="padding:6px;text-align:center;color:var(--text-muted);font-size:9px;">No matching contacts found. Tap <b>📱 .vcf</b> to import a phone contact file.</div>`;
      }
      window._cachedPickerContacts = all;
      return all.slice(0, 30).map((c, i) => `
        <div onclick="selectContactFromSliderList(${i})" style="cursor:pointer;padding:5px 7px;border-radius:6px;background:var(--bg-surface);border:1px solid ${c.isTargetCompany ? 'var(--primary)' : 'var(--border-color)'};display:flex;justify-content:space-between;align-items:center;gap:6px;">
          <div style="min-width:0;overflow:hidden;">
            <div style="font-weight:800;font-size:10px;color:var(--text-main);white-space:nowrap;overflow:hidden;text-overflow:ellipsis;">
              👤 ${escH(c.name)} ${c.company ? `<span style="font-weight:600;color:${c.isTargetCompany ? 'var(--primary)' : 'var(--text-muted)'};">(${escH(c.company)})</span>` : ''}
            </div>
            ${c.position ? `<div style="font-size:9px;color:var(--accent);white-space:nowrap;overflow:hidden;text-overflow:ellipsis;">💼 ${escH(c.position)}</div>` : ''}
            ${(c.email || c.phone) ? `<div style="font-size:8.5px;color:var(--text-secondary);white-space:nowrap;overflow:hidden;text-overflow:ellipsis;">${c.email ? '✉️ ' + escH(c.email) + ' ' : ''}${c.phone ? '📞 ' + escH(c.phone) : ''}</div>` : ''}
          </div>
          <span style="font-size:9px;font-weight:800;color:var(--primary);flex-shrink:0;">Use</span>
        </div>
      `).join('');
    }

    function filterSliderContactPickerList(val) {
      const j = getSelectedJob();
      const listEl = document.getElementById('sl-contact-picker-list');
      if (listEl) listEl.innerHTML = renderSliderContactPickerItems(j, val);
    }

    function selectContactFromSliderList(idx) {
      const c = (window._cachedPickerContacts || [])[idx];
      if (!c) return;
      applyPickedContactToReferralInputs(c);
    }

    function handleReferralVcfFile(inputEl) {
      const file = inputEl?.files?.[0];
      if (!file) return;
      const reader = new FileReader();
      reader.onload = function(evt) {
        const text = String(evt.target?.result || '');
        const fnMatch = text.match(/^FN(?:;[^:]*)?:(.+)$/im);
        const titleMatch = text.match(/^(?:TITLE|ROLE)(?:;[^:]*)?:(.+)$/im);
        const orgMatch = text.match(/^ORG(?:;[^:]*)?:(.+)$/im);
        const emailMatch = text.match(/^EMAIL(?:;[^:]*)?:(.+)$/im);
        const telMatch = text.match(/^TEL(?:;[^:]*)?:(.+)$/im);

        const rawName = fnMatch ? fnMatch[1].trim() : '';
        const rawPos = titleMatch ? titleMatch[1].trim() : (orgMatch ? orgMatch[1].split(';').slice(1).join(' ').trim() : '');
        const rawEmail = emailMatch ? emailMatch[1].trim() : '';
        const rawPhone = telMatch ? telMatch[1].trim() : '';

        applyPickedContactToReferralInputs({
          name: rawName,
          position: rawPos,
          email: rawEmail,
          phone: rawPhone
        });
        inputEl.value = '';
      };
      reader.readAsText(file);
    }

    async function pickReferralFromContactList(sNo) {
      // 1. Try native Device Contact Picker API first (Android Chrome / PWA / TWA)
      if (typeof navigator !== 'undefined' && 'contacts' in navigator && navigator.contacts && typeof navigator.contacts.select === 'function') {
        try {
          let supportedProps = ['name', 'email', 'tel'];
          if (typeof navigator.contacts.getProperties === 'function') {
            const avail = await navigator.contacts.getProperties();
            if (Array.isArray(avail) && avail.length > 0) {
              supportedProps = avail.filter(p => ['name', 'email', 'tel', 'jobTitle', 'title', 'role', 'organization'].includes(p));
              if (supportedProps.length === 0) supportedProps = ['name', 'email', 'tel'];
            }
          }
          const picked = await navigator.contacts.select(supportedProps, { multiple: false });
          if (picked && picked.length > 0) {
            const c = picked[0];
            const rawName = Array.isArray(c.name) ? (c.name[0] || '') : (c.name || '');
            const rawPos = (Array.isArray(c.jobTitle) ? c.jobTitle[0] : c.jobTitle) ||
                           (Array.isArray(c.title) ? c.title[0] : c.title) ||
                           (Array.isArray(c.role) ? c.role[0] : c.role) || '';
            const rawEmail = Array.isArray(c.email) ? (c.email[0] || '') : (c.email || '');
            const rawPhone = Array.isArray(c.tel) ? (c.tel[0] || '') : (c.tel || '');
            applyPickedContactToReferralInputs({
              name: rawName,
              position: rawPos,
              email: rawEmail,
              phone: rawPhone
            });
            return;
          }
          return;
        } catch (err) {
          // Fall through to inline Contact List picker if native Contact Picker is unsupported in current WebView/browser
        }
      }

      // 2. Fallback: Toggle inline Contact List Picker (CareerPulse Contacts + .vcf Phone Contact Import)
      window._showSliderContactPicker = !window._showSliderContactPicker;
      const drawer = document.getElementById('sl-contact-picker-drawer');
      if (drawer) {
        drawer.style.display = window._showSliderContactPicker ? 'block' : 'none';
        if (window._showSliderContactPicker) {
          filterSliderContactPickerList('');
          const searchEl = document.getElementById('sl-contact-picker-search');
          if (searchEl) searchEl.focus();
        }
      } else {
        renderHalfSlider();
      }
    }

    function startEditSliderReferral(sNo, idx) {
      const j = getSelectedJob();
      const compRefs = getCompanyReferrals(j);
      const target = compRefs[idx];
      if (!target) return;
      editingReferralState = {
        sNo: String(sNo),
        idx,
        originalName: target.name,
        name: target.name || '',
        position: target.position || '',
        email: target.email || '',
        phone: target.phone || ''
      };
      renderHalfSlider();
      const nameInput = document.getElementById('sl-ref-name');
      if (nameInput) nameInput.focus();
    }

    function cancelEditSliderReferral() {
      editingReferralState = null;
      renderHalfSlider();
    }

    function saveSliderReferral(sNo) {
      const j = getSelectedJob();
      const name = (document.getElementById('sl-ref-name')?.value || '').trim();
      const position = (document.getElementById('sl-ref-position')?.value || '').trim();
      const email = (document.getElementById('sl-ref-email')?.value || '').trim();
      const phone = (document.getElementById('sl-ref-phone')?.value || '').trim();
      if (!name) {
        notifyToast('⚠️ Please enter the referral Name.');
        return;
      }
      if (!liveState.refContacts) liveState.refContacts = [];

      const isEditing = Boolean(editingReferralState && String(editingReferralState.sNo) === String(sNo));
      const origName = isEditing ? editingReferralState.originalName : '';

      if (isEditing) {
        let updatedInVault = false;
        for (const rc of liveState.refContacts) {
          if (isSameCompany(j.company, rc.company_name) && String(rc.referrer_name || '').toLowerCase().trim() === origName.toLowerCase().trim()) {
            rc.referrer_name = name;
            rc.position = position;
            rc.referrer_email = email;
            rc.referrer_phone = phone;
            rc.notes = position;
            updatedInVault = true;
          }
        }
        if (!updatedInVault) {
          liveState.refContacts.push({
            company_name: j.company,
            referrer_name: name,
            position: position,
            referrer_email: email,
            referrer_phone: phone,
            notes: position
          });
        }
        for (const item of (liveState.jobs || [])) {
          if (isSameCompany(item.company, j.company)) {
            if (item.reference && String(item.reference).toLowerCase().trim() === origName.toLowerCase().trim()) {
              item.reference = name;
            }
            item.referralPosition = position;
            item.referralEmail = email;
            item.referralPhone = phone;
          }
        }
        editingReferralState = null;
        callBackendJobAction(sNo, 'save_notes', {
          company: j.company,
          originalReferralName: origName,
          referralName: name,
          referralPosition: position,
          referralEmail: email,
          referralPhone: phone
        });
        notifyToast(`✅ Saved changes to referral ${name} for ${j.company}!`);
      } else {
        liveState.refContacts.push({
          company_name: j.company,
          referrer_name: name,
          position: position,
          referrer_email: email,
          referrer_phone: phone,
          notes: position
        });
        for (const item of (liveState.jobs || [])) {
          if (isSameCompany(item.company, j.company)) {
            item.referralName = item.referralName ? (item.referralName + ', ' + name) : name;
            item.reference = item.referralName;
            item.referralPosition = position;
            item.referralEmail = email;
            item.referralPhone = phone;
          }
        }
        callBackendJobAction(sNo, 'save_notes', {
          company: j.company,
          referralName: name,
          referralPosition: position,
          referralEmail: email,
          referralPhone: phone
        });
        notifyToast(`✅ Added referral ${name} for ${j.company}!`);
      }
      renderSimulator();
      renderHalfSlider();
    }

    // =========================================================================
    // 1 & 2. PORTALS & COMPANY CAREER WEBSITES AUTH VAULT VIEW
    // =========================================================================
    function formatPortalCleanName(rawName) {
      return String(rawName || '')
        .replace(/\s*Jobs\s*&\s*Easy\s*Apply/ig, '')
        .replace(/\s*Easy\s*Apply/ig, '')
        .replace(/\s*India\s*\/\s*Global/ig, '')
        .replace(/\s*&\s*Fintech/ig, '')
        .replace(/\s*\/\s*Big-4\s*Portals/ig, '')
        .replace(/\s*\([^)]*\)/g, '')
        .replace(/\s+Careers$/i, '')
        .replace(/\.(com|io|tech|co\.in)$/i, '')
        .trim() || String(rawName || 'Portal');
    }

    function getPortalTargetUrl(p) {
      if (p && p.url && /^https?:\/\//i.test(p.url)) return p.url;
      const dom = String((p && p.domain) || '').replace(/\s*\([^)]*\)/g, '').trim();
      if (!dom) return 'https://www.google.com';
      return /^https?:\/\//i.test(dom) ? dom : ('https://' + dom);
    }

    function togglePortalSearchBar(openState) {
      showPortalSearch = (typeof openState === 'boolean') ? openState : !showPortalSearch;
      if (!showPortalSearch) {
        portalSearchQuery = '';
      }
      renderSimulator();
      if (showPortalSearch) {
        setTimeout(function() {
          const inp = document.getElementById('portal-search-input');
          if (inp) inp.focus();
        }, 20);
      }
    }

    function updatePortalSearchInput(val) {
      portalSearchQuery = String(val || '');
      const listContainer = document.getElementById('portal-cards-list-container');
      if (listContainer) {
        listContainer.innerHTML = buildPortalCardsListHtml();
      } else {
        renderSimulator();
      }
    }

    function buildPortalCardsListHtml() {
      initPortalVaultState();
      if (portalSubTab !== 'portals' && portalSubTab !== 'companies') {
        portalSubTab = 'portals';
      }
      const portalsOnly = portalVaultState.filter(p => p.kind === 'portal');
      const companiesOnly = portalVaultState.filter(p => p.kind === 'company');
      let baseList = showPortalSearch
        ? portalVaultState.slice()
        : (portalSubTab === 'companies' ? companiesOnly.slice() : portalsOnly.slice());

      if (showPortalSearch && portalSearchQuery.trim()) {
        const q = portalSearchQuery.trim().toLowerCase();
        baseList = baseList.filter(p => {
          const cleanName = formatPortalCleanName(p.name).toLowerCase();
          const rawName = String(p.name || '').toLowerCase();
          const dom = String(p.domain || '').toLowerCase();
          return cleanName.includes(q) || rawName.includes(q) || dom.includes(q);
        });
      }

      // Requirement 11: Pending authorizations on top, followed by Logged In ones
      baseList.sort((a, b) => {
        const aConn = a.status === 'CONNECTED' ? 1 : 0;
        const bConn = b.status === 'CONNECTED' ? 1 : 0;
        return aConn - bConn;
      });

      if (baseList.length === 0) {
        return `
          <div class="m-card" style="text-align:center;padding:22px 12px;color:var(--text-muted);font-size:11px;">
            No matching portals or company websites found.
          </div>
        `;
      }

      return baseList.map(p => {
        const isConn = p.status === 'CONNECTED';
        const isOpen = Boolean(openPortalAuthIds[p.id]);
        const cleanName = formatPortalCleanName(p.name);
        const siteUrl = getPortalTargetUrl(p);
        const cardBorderStyle = isConn
          ? 'border: 2px solid #10b981 !important; background: linear-gradient(145deg, rgba(16, 185, 129, 0.14) 0%, rgba(16, 185, 129, 0.04) 50%, var(--bg-surface) 100%) !important;'
          : 'border: 2px solid #eab308 !important; background: linear-gradient(145deg, rgba(234, 179, 8, 0.18) 0%, rgba(234, 179, 8, 0.05) 50%, var(--bg-surface) 100%) !important;';

        const modeLabelMap = {
          'AUTO_APPLY': 'Auto-Apply Enabled',
          'REVIEW_FIRST': 'Review Before Apply',
          'DISCOVER_ONLY': 'Fetch JDs Only'
        };
        const currentModeLabel = modeLabelMap[p.mode] || 'Review Before Apply';

        return `
          <div class="m-card" style="${cardBorderStyle}">
            <div style="display:flex;justify-content:space-between;align-items:flex-start;gap:6px;">
              <div>
                <div style="font-size:13px;font-weight:800;">
                  <a href="${escH(siteUrl)}" target="_blank" rel="noopener noreferrer" style="color:var(--accent);text-decoration:underline;text-underline-offset:2px;">${escH(cleanName)}</a>
                </div>
                <div style="font-size:9.5px;color:var(--text-muted);margin-top:3px;">
                  ${escH(p.account)}
                </div>
                <div style="font-size:9.5px;color:var(--text-muted);margin-top:2px;">
                  <strong style="color:#eab308;font-weight:800;">${p.jobsCount} jobs</strong> • <strong style="color:#10b981;font-weight:800;">${p.appliedCount} applied</strong>
                </div>
              </div>
              <span style="font-size:8.5px;padding:3px 7px;border-radius:99px;font-weight:800;background:${isConn ? 'var(--success-soft)' : 'var(--warning-soft)'};color:${isConn ? 'var(--success)' : 'var(--warning)'};white-space:nowrap;">
                ${isConn ? 'Logged In' : 'Pending'}
              </span>
            </div>

            <div style="display:flex;justify-content:space-between;align-items:center;gap:8px;margin-top:8px;padding-top:6px;border-top:1px solid var(--border-color);">
              <div onclick="openPortalApplyModeModal('${p.id}')" style="cursor:pointer;min-width:0;max-width:58%;background:var(--bg-surface-2);border:1px solid var(--border-color);border-radius:8px;padding:5px 10px;font-size:9.5px;font-weight:700;color:var(--text-main);white-space:nowrap;overflow:hidden;text-overflow:ellipsis;" title="${escH(currentModeLabel)} — Tap to change apply status">
                ${escH(currentModeLabel)}
              </div>
