    function saveProfileSettings() {
      syncProfileInputsToState();
      candidateProfileState.openMultiDropdown = null;
      updateBurgerProfileAvatar();
      notifyToast('✅ Profile saved!');
      renderSimulator();
    }

    let ownerSettingsUnlocked = false;
    try {
      ownerSettingsUnlocked = localStorage.getItem('cp_owner_unlocked') === '1';
    } catch (e) {}

    function unlockOwnerSettings() {
      const val = String(document.getElementById('owner-pin-input')?.value || '').trim().toLowerCase();
      if (val === '0808' || val === 'user@example.com' || val === 'sumantob') {
        ownerSettingsUnlocked = true;
        try { localStorage.setItem('cp_owner_unlocked', '1'); } catch (e) {}
        notifyToast('Owner Settings Unlocked!');
        renderSimulator();
      } else {
        notifyToast('Access Denied — Owner Passcode Required');
      }
    }

    function lockOwnerSettings() {
      ownerSettingsUnlocked = false;
      try { localStorage.removeItem('cp_owner_unlocked'); } catch (e) {}
      notifyToast('Settings locked to outside public!');
      renderSimulator();
    }

    function renderMobileSettingsTab(body) {
      const s = appAutomationSettings;
      const curTheme = document.documentElement.getAttribute('data-theme') || 'tabler-dark';
      if (!ownerSettingsUnlocked) {
        body.innerHTML = `
          <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:8px;">
            <button class="m-btn m-btn-ghost" style="padding:4px 10px;font-size:10.5px;font-weight:800;" onclick="goBackPhoneTab()">
              <i class="bi bi-arrow-left"></i> Back
            </button>
            <span style="font-size:10px;color:var(--warning);font-weight:800;">Private Owner Gate</span>
          </div>
          <div class="m-card" style="border-color:var(--warning);text-align:center;padding:18px 14px;">
            <div style="font-size:26px;margin-bottom:6px;">🔒</div>
            <div style="font-size:13px;font-weight:800;color:var(--text-main);margin-bottom:4px;">Settings Closed to Outside Public</div>
            <div style="font-size:10.5px;color:var(--text-muted);margin-bottom:12px;">
              App &amp; Automation Settings are restricted to the owner (<code>user@example.com</code>). Enter your Owner PIN or email to unlock on this device:
            </div>
            <input id="owner-pin-input" type="password" class="m-input mb-2" placeholder="Enter Owner PIN (0808) or Owner Email" aria-label="Owner PIN or Email" style="text-align:center;font-weight:700;" onkeydown="if(event.key==='Enter')unlockOwnerSettings()" />
            <button type="button" class="m-btn m-btn-primary w-100" onclick="unlockOwnerSettings()">
              Unlock Owner Settings
            </button>
          </div>
        `;
        return;
      }
      body.innerHTML = `
        <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:8px;">
          <button class="m-btn m-btn-ghost" style="padding:4px 10px;font-size:10.5px;font-weight:800;" onclick="goBackPhoneTab()">
            <i class="bi bi-arrow-left"></i> Back
          </button>
          <div style="display:flex;align-items:center;gap:6px;">
            <span style="font-size:10px;color:var(--success);font-weight:800;">Owner Unlocked</span>
            <button type="button" class="m-btn m-btn-danger" style="padding:3px 8px;font-size:10px;" onclick="lockOwnerSettings()">Lock</button>
          </div>
        </div>

        <!-- AI Auto-Apply & JD Relevance Gate Settings -->
        <div class="m-card" style="border-color:rgba(16,185,129,0.4);">
          <div style="font-size:11.5px;font-weight:800;color:var(--success);margin-bottom:6px;">
            <i class="bi bi-robot"></i> AI Auto-Apply &amp; JD Relevance Score Gate
          </div>
          <div style="display:grid;grid-template-columns:1fr 1fr;gap:6px;margin-bottom:8px;">
            <div>
              <label style="font-size:8.8px;color:var(--text-muted);font-weight:700;">MIN JD SCORE FOR AUTO-APPLY (%)</label>
              <input id="set-min-score" type="number" class="m-input" value="${s.minJdScoreAutoApply}" min="70" max="99" />
            </div>
            <div>
              <label style="font-size:8.8px;color:var(--text-muted);font-weight:700;">DAILY AUTO-APPLY CAP</label>
              <input id="set-daily-cap" type="number" class="m-input" value="${s.dailyAutoApplyCap}" min="5" max="100" />
            </div>
          </div>

          <div style="background:var(--bg-surface-2);padding:7px 9px;border-radius:9px;margin-bottom:6px;font-size:10px;">
            <label style="display:flex;justify-content:space-between;align-items:center;cursor:pointer;">
              <span><strong>Auto-Inject Missing JD Keywords</strong><br><span style="font-size:8.8px;color:var(--text-muted);">Boosts Resume &amp; Cover Letter score ≥92% before applying</span></span>
              <input id="set-auto-inject" type="checkbox" ${s.autoInjectMissingKeywords ? 'checked' : ''} style="width:15px;height:15px;" />
            </label>
          </div>

