-- Ensure user_id column exists across all tenant tables and enforce PostgreSQL Row-Level Security (RLS)
ALTER TABLE resume_generations ADD COLUMN IF NOT EXISTS user_id INT DEFAULT 1;
ALTER TABLE cover_letter_generations ADD COLUMN IF NOT EXISTS user_id INT DEFAULT 1;
ALTER TABLE learned_rules ADD COLUMN IF NOT EXISTS user_id INT DEFAULT 1;
ALTER TABLE linkedin_activity_log ADD COLUMN IF NOT EXISTS user_id INT DEFAULT 1;
ALTER TABLE linkedin_network_contacts ADD COLUMN IF NOT EXISTS user_id INT DEFAULT 1;
ALTER TABLE portal_credentials_vault ADD COLUMN IF NOT EXISTS user_id INT DEFAULT 1;
ALTER TABLE portal_apply_limits ADD COLUMN IF NOT EXISTS user_id INT DEFAULT 1;
ALTER TABLE job_hunter_eod_log ADD COLUMN IF NOT EXISTS user_id INT DEFAULT 1;

DO $$
DECLARE
  tbl TEXT;
  tenant_tables TEXT[] := ARRAY[
    'resume_generations',
    'cover_letter_generations',
    'learned_rules',
    'linkedin_activity_log',
    'linkedin_network_contacts',
    'portal_credentials_vault',
    'portal_apply_limits',
    'job_hunter_eod_log',
    'user_gdpr_consents'
  ];
BEGIN
  FOREACH tbl IN ARRAY tenant_tables LOOP
    IF EXISTS (SELECT 1 FROM information_schema.tables WHERE table_schema = 'public' AND table_name = tbl) THEN
      EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY;', tbl);
      EXECUTE format('ALTER TABLE %I FORCE ROW LEVEL SECURITY;', tbl);
      EXECUTE format('DROP POLICY IF EXISTS tenant_isolation_policy ON %I;', tbl);
      EXECUTE format(
        'CREATE POLICY tenant_isolation_policy ON %I ' ||
        'USING (user_id = COALESCE(NULLIF(current_setting(''app.current_user_id'', true), '''')::int, 1)) ' ||
        'WITH CHECK (user_id = COALESCE(NULLIF(current_setting(''app.current_user_id'', true), '''')::int, 1));',
        tbl
      );
    END IF;
  END LOOP;
END $$;


CREATE TABLE IF NOT EXISTS user_gdpr_consents (
  user_id INT PRIMARY KEY DEFAULT 1,
  email TEXT NOT NULL DEFAULT 'user@example.com',
  consent_profile_processing BOOLEAN DEFAULT TRUE,
  consent_ai_tailoring BOOLEAN DEFAULT TRUE,
  consent_portal_automation BOOLEAN DEFAULT TRUE,
  consent_linkedin_outreach BOOLEAN DEFAULT TRUE,
  consent_analytics BOOLEAN DEFAULT FALSE,
  ip_hash TEXT DEFAULT '',
  policy_version TEXT DEFAULT '2026.10-GDPR',
  consented_at TIMESTAMPTZ DEFAULT NOW(),
